(function () {
  "use strict";

  var currentScript = document.currentScript;
  var baseUrl = currentScript && currentScript.src
    ? currentScript.src.split("?")[0].replace(/\/[^/]+$/, "")
    : "https://cdn.jsdelivr.net/gh/Narek1990/CSS@main/donebets";
  var cssHref = baseUrl + "/donebets.css?v=" + Date.now();
  var targetSelector = "span.app-ltr-1phvdj0, span.app-rtl-1phvdj0";
  var svgMarkup = atob("");

  function ensureCss() {
    var existing = document.querySelector('link[data-donebets-css="true"]');

    if (existing) {
      existing.href = cssHref;
      return;
    }

    document.head.appendChild(
      Object.assign(document.createElement("link"), {
        rel: "stylesheet",
        href: cssHref,
        "data-donebets-css": "true"
      })
    );
  }

  function injectSvg(element) {
    if (!element || element.querySelector("svg[data-donebets-giftbox='true']")) {
      return;
    }

    element.innerHTML = svgMarkup;

    var svg = element.querySelector("svg");
    if (!svg) {
      return;
    }

    svg.setAttribute("data-donebets-giftbox", "true");
    element.setAttribute("data-donebets-applied", "true");
  }

  function apply() {
    ensureCss();
    document.querySelectorAll(targetSelector).forEach(injectSvg);
  }

  apply();

  new MutationObserver(apply).observe(document.documentElement, {
    childList: true,
    subtree: true
  });
})();
